"""Prints the Homebrew formula of one release.

    python3 .github/scripts/render-formula.py VERSION SHA256SUMS > Formula/rune.rb
    python3 .github/scripts/render-formula.py --self-test

Standard library only. The digests come from the release's SHA256SUMS.
"""

import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
RELEASES = "https://github.com/AadiXC0DE/Rune/releases/download"
TARGETS = {
    ("macos", "arm"): "aarch64-apple-darwin",
    ("macos", "intel"): "x86_64-apple-darwin",
    ("linux", "arm"): "aarch64-unknown-linux-musl",
    ("linux", "intel"): "x86_64-unknown-linux-musl",
}


def digests(sums_text):
    found = {}
    for line in sums_text.splitlines():
        fields = line.split()
        if len(fields) == 2:
            found[fields[1].lstrip("*")] = fields[0].lower()
    return found


def block(platform, sums, version):
    lines = [f"  on_{platform} do"]
    for cpu in ("arm", "intel"):
        target = TARGETS[(platform, cpu)]
        name = f"rune-{version}-{target}.tar.gz"
        if name not in sums:
            raise SystemExit(f"render-formula: SHA256SUMS has no line for {name}")
        lines += [
            f"    on_{cpu} do",
            f'      url "{RELEASES}/v#{{version}}/rune-#{{version}}-{target}.tar.gz"',
            f'      sha256 "{sums[name]}"',
            "    end",
        ]
    lines.append("  end")
    return "\n".join(lines)


def render(version, sums_text):
    version = version.lstrip("v")
    sums = digests(sums_text)
    return f'''# Generated by .github/scripts/render-formula.py from the release's SHA256SUMS.
#
# `rune` is already the name of an embeddable language in homebrew/core, and core
# wins a bare name, so this is installed as `aadixc0de/tap/rune`.
class Rune < Formula
  desc "Native coding agent harness"
  homepage "https://rune.heyaadi.com"
  version "{version}"
  license "Apache-2.0"

  livecheck do
    url "https://github.com/AadiXC0DE/Rune/releases/latest"
    strategy :github_latest
  end

{block("macos", sums, version)}

{block("linux", sums, version)}

  def install
    bin.install "rune"
  end

  def caveats
    "Run rune connect to choose a provider."
  end

  test do
    assert_match version.to_s, shell_output("#{{bin}}/rune --version")
  end
end
'''


def self_test():
    fixtures = HERE / "fixtures"
    rendered = render("v1.2.3", (fixtures / "rune.rb.SHA256SUMS").read_text())
    expected = (fixtures / "rune.rb.expected").read_text()
    if rendered != expected:
        raise SystemExit("render-formula: the formula differs from fixtures/rune.rb.expected")
    print("ok")


def main():
    arguments = sys.argv[1:]
    if arguments == ["--self-test"]:
        self_test()
    elif len(arguments) == 2:
        sys.stdout.write(render(arguments[0], pathlib.Path(arguments[1]).read_text()))
    else:
        raise SystemExit(__doc__)


main()
